// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.base;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.PrintWriter;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;

import jakarta.servlet.ServletConfig;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

class WorkbenchHtmlShellTest {
	@Test
	void deploymentDescriptorDoesNotConfigureLegacyTransformationPath() throws Exception {
		String webXml = Files.readString(Path.of("src/main/webapp/WEB-INF/web.xml"), StandardCharsets.UTF_8);

		assertThat(webXml).doesNotContain("<param-name>transformations</param-name>", "/transformations");
	}

	@Test
	void bootsTheLocalRendererFromTheContextPathWithoutTransformationConfiguration() throws Exception {
		HttpServletRequest request = mock(HttpServletRequest.class);
		HttpServletResponse response = mock(HttpServletResponse.class);
		ServletConfig config = mock(ServletConfig.class);
		StringWriter body = new StringWriter();
		when(request.getContextPath()).thenReturn("/rdf4j-workbench");
		when(response.getWriter()).thenReturn(new PrintWriter(body));

		WorkbenchHtmlShell.write(request, response, config, "summary");

		assertThat(body.toString())
				.contains("data-workbench-view=\"summary\"")
				.contains("data-workbench-base-path=\"/rdf4j-workbench\"")
				.contains("/rdf4j-workbench/styles/query.css")
				.contains("/rdf4j-workbench/scripts/workbenchApp.js")
				.doesNotContain("/transformations", ".xsl");
		verify(response).setHeader("Cache-Control", "no-cache, no-store");
		verify(response).addHeader("Vary", "Accept");
	}

	@Test
	void usesTheExplicitBasePathForPrefixMountedWorkbench() throws Exception {
		HttpServletRequest request = mock(HttpServletRequest.class);
		HttpServletResponse response = mock(HttpServletResponse.class);
		ServletConfig config = mock(ServletConfig.class);
		StringWriter body = new StringWriter();
		when(config.getInitParameter("workbenchBasePath")).thenReturn("/rdf4j-workbench");
		when(response.getWriter()).thenReturn(new PrintWriter(body));

		WorkbenchHtmlShell.write(request, response, config, "summary");

		assertThat(body.toString()).contains("data-workbench-base-path=\"/rdf4j-workbench\"")
				.contains("/rdf4j-workbench/scripts/workbenchApp.js");
	}
}
